/// A small, local prior for proportional glyph widths. It predicts dimensions,
/// not contours or a probability of correctness. Curves remain provisional.
/// The reproducible training pipeline is in scripts/starter-research/.
enum FontLabWidthPrior {
    struct Prediction {
        let widths: [String: Double]
        let upperOrigin: Double
        let lowerOrigin: Double

        func origin(for character: String) -> Double {
            character == character.uppercased() ? upperOrigin : lowerOrigin
        }
    }

    private struct Measurement {
        let width: Double
        let height: Double
        let origin: Double
    }

    static func predict(_ sources: [String: FontLabGlyph]) -> Prediction? {
        var measurements: [String: Measurement] = [:]
        for character in ["H", "O", "n", "o", "p"] {
            guard let glyph = sources[character], glyph.character == character,
                  glyph.isValid, glyph.hasArtwork else { return nil }
            let paths = FontLabVectorMath.paths(in: glyph)
            guard !paths.isEmpty, paths.allSatisfy(\.closed) else { return nil }
            let ink = CGMutablePath()
            paths.forEach { ink.addPath($0.cgPath) }
            let box = ink.boundingBoxOfPath
            guard !box.isNull, box.width.isFinite, box.height.isFinite,
                  box.width > 0, box.height > 0 else { return nil }
            measurements[character] = Measurement(width: box.width/1000*glyph.resolvedDesignWidth,
                                                    height: box.height/1000,
                                                    origin: max(0, box.minX/1000*glyph.resolvedDesignWidth))
        }
        guard let h = measurements["H"], let o = measurements["O"],
              let n = measurements["n"], let lowerO = measurements["o"], let p = measurements["p"] else { return nil }
        let raw = [log(o.width/h.width), log(n.width/h.width), log(lowerO.width/n.width), log(p.width/n.width),
                   log(h.width/h.height), log(n.height/h.height), log(p.height/n.height), log(o.height/h.height)]
        let normalized = raw.indices.map { (raw[$0]-featureMeans[$0])/featureScales[$0] }
        // Keep the existing construction outside the measured training range.
        // This check is a fallback boundary, not calibrated confidence.
        guard normalized.allSatisfy({ $0.isFinite && abs($0) < 4 }) else { return nil }
        let input = [1.0]+normalized
        var widths: [String: Double] = [:]
        for (index, character) in targetCharacters.enumerated() {
            let logRatio = zip(input, coefficients[index]).reduce(0.0) { $0+$1.0*$1.1 }
            let base = character == character.uppercased() ? h.width : n.width
            let width = base*exp(logRatio)
            // Do not clamp an unsupported prediction into a plausible-looking
            // result. The caller can use the existing template for this letter.
            if width.isFinite, (0.02...2.5).contains(width) { widths[character] = width }
        }
        guard !widths.isEmpty else { return nil }
        return Prediction(widths: widths, upperOrigin: h.origin, lowerOrigin: n.origin)
    }

